<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Client\Infrastructure\Driven;

use Civi\Lughauth\Features\Access\Tenant\Domain\Gateway\TenantQueryRepositoryGateway;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\Gateway\TrustedClientQueryRepositoryGateway;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClient;

/**
 * Resolves a TrustedClient by code as seen from a tenant (task 022).
 *
 * A client belongs to one tenant or, with tenant = null, is global: managed only by root and
 * usable from every tenant. The tenant's own client wins over a global one with the same code,
 * and a client of another tenant is never returned. An unknown tenant only sees global clients.
 */
class TrustedClientFinder
{
    /** @var array<string, ?TenantRef> tenant reference by tenant name, cached for the request */
    private array $tenantRefs = [];

    public function __construct(
        private readonly TrustedClientQueryRepositoryGateway $clients,
        private readonly TenantQueryRepositoryGateway $tenants,
    ) {
    }

    /**
     * Finds the client visible from the tenant with the given name (the {tenant} path segment).
     */
    public function findForTenantName(string $tenantName, string $code): ?TrustedClient
    {
        return $this->findForTenant($this->tenantRef($tenantName), $code);
    }

    /**
     * Finds the client visible from the given tenant: its own client first, then the global one.
     */
    public function findForTenant(?TenantRef $tenant, string $code): ?TrustedClient
    {
        if ($code === '') {
            return null;
        }
        $owned = $tenant !== null ? $this->clients->findOneByTenantAndCode($tenant, $code) : null;
        return $owned ?? $this->clients->findOneByTenantAndCode(null, $code);
    }

    /**
     * The reference of the tenant with the given name, or null when it does not exist.
     */
    public function tenantRef(string $tenantName): ?TenantRef
    {
        if (!array_key_exists($tenantName, $this->tenantRefs)) {
            $uid = $tenantName !== '' ? $this->tenants->findOneByName($tenantName)?->uid() : null;
            $this->tenantRefs[$tenantName] = $uid !== null && $uid !== '' ? new TenantRef($uid) : null;
        }
        return $this->tenantRefs[$tenantName];
    }
}
